/** Test-only silence. Never an actor recording or an uploadable production asset. */
export function syntheticWav(): Buffer {
  const samples = 1_600;
  const bytes = Buffer.alloc(44 + samples * 2);
  bytes.write("RIFF", 0);
  bytes.writeUInt32LE(bytes.length - 8, 4);
  bytes.write("WAVEfmt ", 8);
  bytes.writeUInt32LE(16, 16);
  bytes.writeUInt16LE(1, 20);
  bytes.writeUInt16LE(1, 22);
  bytes.writeUInt32LE(16_000, 24);
  bytes.writeUInt32LE(32_000, 28);
  bytes.writeUInt16LE(2, 32);
  bytes.writeUInt16LE(16, 34);
  bytes.write("data", 36);
  bytes.writeUInt32LE(samples * 2, 40);
  return bytes;
}

// 100 ms silence, encoded once with FFmpeg/libmp3lame (not required by tests):
// ffmpeg -f lavfi -i anullsrc=channel_layout=mono:sample_rate=16000 -t 0.1
//   -c:a libmp3lame -b:a 16k -write_xing 0 -id3v2_version 0 -map_metadata -1 silence.mp3
export function syntheticMp3(): Buffer {
  return Buffer.from(
    "",
    "base64",
  );
}
